    const hard = G.hard && !G.cfg.tutorial;
    G.time = G.cfg.duration * (hard ? 0.85 : 1);
    G.elapsed = 0;
    G.spawnIdx = 0;
    G.barkT = rand(16, 24);
    G.maxScans = G.scans = hard ? Math.max(1, G.cfg.scans - 1) : G.cfg.scans;
    G.boOn = false;
    G.boT = rand(9, 13);
    G.rmT = rand(10, 14);
