    const missed = club.patrons.filter((p) => p.isHuman && p.alive).length;
    const s = { caught: G.stats.caught, missed, wrong: G.stats.wrong };
    s.profit = 500 + s.caught * 100 - missed * 100 - s.wrong * 150;
    s.grade = gradeOf(s);
