    if (gi.point.distanceTo(d.g.position) > 0.15) return false;
    gi.anchor.updateMatrixWorld(true);
    d.g.updateMatrixWorld(true);
    d.offset = new Matrix4().copy(gi.anchor.matrixWorld).invert().multiply(d.g.matrixWorld);
