      if (H.sweat > 60) hText(c, vr ? TR("\uC5BC\uAD74\uC5D0 \uC190!", "hand to face!") : TR("F \uAFB9", "hold F"), gx + 256, gy + 22, `700 18px ${FONT}`, "#bfe9ff");
