    const gx = cx - 470, gw = 940, gy = 100, gh = 42;
    hText(c, TR("\uC758\uC2EC", "SUSPICION"), gx, gy + gh / 2, `900 30px ${FONT}`, "#ffd0d8", "left");
    const bx = gx + 120, bw = gw - 120;
