      hText(c, TR("\uAC10\uC2DC \uC911 \u2014 CCTV\uAC00 \uBCF4\uACE0 \uC788\uB2E4", "WATCHED \u2014 CCTV on you"), cx + 15, 194, `800 26px ${FONT}`, "#ffd0d6", "center");
