  function update(dt, t) {
    up.pvpTick(dt);
    if (H.active || G.state === "human") {
      updateHuman(dt, t);
      return;
    }
    audio.tick();
    updateDialog(dt);
    if (room.guide.mesh.visible) {
      G.guideT = (G.guideT || 0) - dt;
      if (G.guideT <= 0) {
        G.guideT = 0.1;
        drawGuide(t);
      }
    }
    if (G.recenterT > 0) {
      G.recenterT -= dt;
      if (G.recenterT <= 0) recenter();
    }
    if (G.state === "night") {
      G.time -= dt;
      G.elapsed += dt;
      const sp = G.cfg.spawns;
      while (G.spawnIdx < sp.length && G.elapsed >= sp[G.spawnIdx][0]) spawnPatron(sp[G.spawnIdx++][1], false);
      G.barkT -= dt;
      if (G.barkT <= 0) {
        G.barkT = rand(22, 32);
        if (!D.bark && G.cfg.barks.length) bark(BENE, pick(G.cfg.barks), 6);
      }
      if (G.cfg.blackout) {
        G.boT -= dt;
        if (G.boT <= 0) {
          G.boOn = !G.boOn;
          if (G.boOn) {
            G.boT = rand(7, 9);
            G.boFlick = 0.7;
            audio.sfx("powerDown");
            if (!D.bark) bark(SYS, TR("\uC815\uC804! CCTV\uB97C \uC801\uC678\uC120 \uBAA8\uB4DC\uB85C \uC804\uD658\uD569\uB2C8\uB2E4.", "Blackout! Switching CCTV to infrared."), 3);
          } else {
            G.boT = rand(13, 18);
            G.boFlick = 0.4;
            audio.sfx("powerUp");
          }
        }
      }
      if (G.cfg.remix && G.dj && audio.playing) {
        G.rmT -= dt;
        if (G.rmT <= 0) {
          G.rmT = rand(13, 19);
          const r = pick([0.8, 0.9, 1.15, 1.3].filter((x) => x !== audio.rate));
          audio.setRate(r);
          audio.sfx("scratch");
          bark(G.dj.name, pick(r > 1 ? LINES.remixUp : LINES.remixDown), 3);
        }
      }
      if (G.time <= 0) {
        G.time = 0;
        endNight();
      }
    }
    const darkGoal = G.state === "night" && G.boOn ? 1 : 0;
    club.dark += (darkGoal - club.dark) * Math.min(1, dt * (darkGoal ? 3 : 5));
    if (G.boFlick > 0) {
      G.boFlick -= dt;
      club.dark = Math.random() < 0.5 ? 0.9 : 0.15;
    }
    for (const m of room.monitors) m.uniforms.tint.value.lerpVectors(m.baseTint, THERMAL_TINT, club.dark);
    if (G.scanning) {
      G.scanning.t += dt;
      const p = G.scanning.p;
      if (!p.alive) G.scanning = null;
      else if (G.scanning.t >= 1.7) {
        p.scanned = true;
        G.scanning = null;
        audio.sfx("scanDone");
        if (p.isHuman) G.tut.scannedHuman = true;
        else if (G.cfg.tutorial) bark(BENE, LINES.scanRobotTut, 5);
      }
    }
    if (G.djSwapT > 0) {
      G.djSwapT -= dt;
      if (G.djSwapT <= 0 && canAct()) spawnDJ(false, true);
    }
    if (G.roomScanT != null && !G.roomScanDone) {
      G.roomScanT += dt;
      if (G.roomScanT >= 2.6) {
        G.roomScanDone = true;
        audio.sfx("scanDone");
        room.monitors.forEach((m) => m.uniforms.glitch.value = 1.5);
      }
    }
    if (G.sel && G.sel.gone) G.sel = null;
    if (G.endT != null) G.endT -= dt;
    if (G.endingFall && rig.position.y > -3) rig.position.y -= dt * 1.2;
    fade.material.opacity += (G.fadeTo - fade.material.opacity) * Math.min(1, dt * 2.5);
    const beat = audio.beat() ?? (G.state === "title" ? t * 2 : null);
    club.update(dt, t, beat);
    club.setMarkers(G.hover, G.sel, t);
    updateZoom(dt, t);
    if (!renderer.xr.isPresenting) camera.rotation.set(pitch, yaw, 0);
    updateHands(dt);
    if (up.LOBBY.active) up.lobbyUpdate(dt, t);
    else {
      updatePoke();
      updateItems(dt);
      updatePointers();
    }
    room.update(dt, t);
    updatePanels(dt, t);
  }
  var frameNo = 0;
  function renderCCTV() {
    const xrOn = renderer.xr.enabled;
    const prev = renderer.getRenderTarget();
    renderer.xr.enabled = false;
    renderer.setRenderTarget(room.zoom.rt);
    renderer.render(club.scene, club.zoomCam);
    const perFrame = renderer.xr.isPresenting ? 1 : 2;
    for (let k = 0; k < perFrame; k++) {
      const m = room.cams[(frameNo * perFrame + k) % 4];
      renderer.setRenderTarget(m.rt);
      renderer.render(club.scene, m.cam);
    }
    renderer.setRenderTarget(prev);
    renderer.xr.enabled = xrOn;
    frameNo++;
  }

  // src/lobby.js
