    if (!lsGet(info.tut)) opts.push({ mode: "tut", label: TR("\uD29C\uD1A0\uB9AC\uC5BC", "Tutorial") });
    opts.push({ mode: "play", label: TR("\uD50C\uB808\uC774", "Play") });
