      c.fillStyle = "#ffd400";
      c.fillText(TR("\uC624\uC77C = \uAC10\uC2DC \xB7 \uCE75\uD14C\uC77C = \uC778\uAC04 \xB7 \uD30C\uB791 = \uB300\uACB0", "OIL = Security \xB7 COCKTAIL = Human \xB7 BLUE = Versus"), 18, 300);
